.app-shell {
  display: grid;
  grid-template-columns: 220px 1fr;
  grid-template-rows: 56px 1fr;
  min-height: 100vh;
}

.app-header {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 1rem;
  background: #1f2937;
  color: white;
}

.app-sidebar { padding: 1rem; border-right: 1px solid #e5e7eb; }
.app-main { padding: 1rem; }

